package com.acaivis.service; import com.acaivis.dto.*; import com.acaivis.exception.*; import com.acaivis.model.Category; import com.acaivis.repository.CategoryRepository; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CategoryService {private final CategoryRepository repo; public CategoryService(CategoryRepository r){repo=r;} public List<CategoryResponse> findAll(){return repo.findAll().stream().map(c->new CategoryResponse(c.getId(),c.getName(),c.isActive())).toList();} public CategoryResponse create(CategoryRequest d){String n=d.name().trim();if(repo.existsByNameIgnoreCase(n))throw new BusinessException("Categoria já cadastrada");Category c=new Category();c.setName(n);return to(repo.save(c));} public CategoryResponse update(Long id,CategoryRequest d){Category c=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Categoria não encontrada"));String n=d.name().trim();if(repo.existsByNameIgnoreCaseAndIdNot(n,id))throw new BusinessException("Categoria já cadastrada");c.setName(n);return to(repo.save(c));} public void delete(Long id){Category c=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Categoria não encontrada"));c.setActive(false);repo.save(c);} public CategoryResponse reactivate(Long id){Category c=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Categoria não encontrada"));c.setActive(true);return to(repo.save(c));} private CategoryResponse to(Category c){return new CategoryResponse(c.getId(),c.getName(),c.isActive());}}
